solution.code:
def parse_csv_row(row: str) -> list[str]:
    fields: list[str] = []
    i, n = 0, len(row)
    while True:
        if i < n and row[i] == '"':
            i += 1
            chars: list[str] = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                if row[i] == '"':
                    if i + 1 < n and row[i + 1] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                chars.append(row[i])
                i += 1
            if i < n and row[i] != ",":
                raise ValueError(f"unexpected character after closing quote at {i}")
            fields.append("".join(chars))
        else:
            end = row.find(",", i)
            end = n if end == -1 else end
            fields.append(row[i:end])
            i = end
        if i >= n:
            return fields
        i += 1  # skip the comma; a trailing comma yields a final empty field
        if i == n:
            fields.append("")
            return fields
